async function matchInExcel() {
  const wb = new ExcelJS.Workbook();
  console.log('Loading excel...');
  await wb.xlsx.readFile('data/(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx');
  const ws = wb.getWorksheet('기업 정보');
  console.log('Searching in worksheet...');

  // Map by corpNo and name
  const excelDataByCorpNo = new Map();
  const excelDataByName = new Map();

  ws.eachRow((row, rowNumber) => {
    if (rowNumber === 1) return;
    const companyName = String(row.getCell(3).value || '').trim();
    const bizNo = String(row.getCell(4).value || '').trim();
    const corpNo = String(row.getCell(25).value || '').trim();

    if (corpNo) {
      excelDataByCorpNo.set(corpNo.replace(/[^0-9]/g, ''), { rowNumber, companyName, bizNo, corpNo });
    }
    if (companyName) {
      excelDataByName.set(companyName, { rowNumber, companyName, bizNo, corpNo });
    }
  });

  console.log(`Built index: ${excelDataByCorpNo.size} by corpNo, ${excelDataByName.size} by name`);

  let foundCount = 0;
  for (const c of targetCompanies) {
    const cleanCorpNo = c.corpNo.replace(/[^0-9]/g, '');
    let match = excelDataByCorpNo.get(cleanCorpNo);
    if (!match) {
      match = excelDataByName.get(c.name);
    }
    if (match && match.bizNo) {
      console.log(`[FOUND] ${c.seq} | ${c.name} | ${c.corpNo} => BizNo: ${match.bizNo} (row ${match.rowNumber})`);
      foundCount++;
    } else {
      console.log(`[NOT FOUND in Excel] ${c.seq} | ${c.name} | ${c.corpNo}`);
    }
  }
  console.log(`Summary: ${foundCount} / ${targetCompanies.length} found in Excel.`);
}

matchInExcel().catch(console.error);
